mapper.select:
SELECT *
FROM delivery_order
WHERE sender_phone = #{phone}
   OR receiver_phone = #{phone}
ORDER BY id DESC

mapper.update:
UPDATE delivery_order SET current_seq = #{seq}, current_station_id = #{stationId}, state = #{state}, version = version + 1 WHERE order_no = #{orderNo}
AND current_seq IS NULL
AND current_seq = #{prevSeq}

UPDATE delivery_order
SET state   = #{to},
    version = version + 1
WHERE order_no = #{orderNo}
  AND state = #{from}
